const REQUIRED_SHELL_HOOKS = [
  'useGetAdminMenuQuery',
  'useInvalidateAllCacheMutation',
]

let shellHooks = null

/**
 * @typedef {object} AdminKitShellHooks
 * @property {function} useGetAdminMenuQuery - RTK Query hook for `getAdminMenu`.
 * @property {function} useInvalidateAllCacheMutation - RTK Query hook for `invalidateAllCache`.
 */

/**
 * Registers shell hooks generated by the app's api (created with `createShellEndpoints`).
 * Call once right after `createApi`.
 * @param {AdminKitShellHooks} hooks
 */
export const initAdminKitShell = (hooks) => {
  const missing = REQUIRED_SHELL_HOOKS.filter((name) => typeof hooks?.[name] !== 'function')

  if (missing.length > 0) {
    throw new Error(`initAdminKitShell: missing hooks: ${missing.join(', ')}`)
  }

  shellHooks = hooks
}

/**
 * @returns {AdminKitShellHooks}
 */
export const getShellHooks = () => {
  if (!shellHooks) {
    throw new Error('admin-kit shell hooks are not initialized. Call initAdminKitShell() after createApi().')
  }

  return shellHooks
}
